(() => {
  'use strict';
  if (window.__franklinSiteRAGLoaded) return;
  window.__franklinSiteRAGLoaded = true;

  const DISCORD = 'https://discord.gg/HgcbPjcyJ';
  const SOURCES = [
    ['faq.html','FAQ',1.55],['guide.html','Installation Guide',1.5],['technicalities.html','Technicalities',1.3],
    ['compatibility.html','Compatibility',1.3],['updates.html','Updates',1.2],['community.html','Community',1.2],
    ['get-started.html','Get Started',1.1],['home.html','Home',1]
  ];
  const STOP=new Set('a an the is are was were be been to of in on at for from with and or but if then than so do does did can could would should will may might i me my you your we our they their it this that these those what why how when where who which about please tell say give get have has had my always when clicking still keeps keep yang dan atau di ke dari untuk pada dengan ini itu saya aku gue kamu anda tentang apa bagaimana gimana kenapa apakah bisa tidak nggak ga gak tolong kasih jelaskan'.split(/\s+/));
  const ALIAS={crashes:'crash',crashing:'crash',crashed:'crash',forceclose:'crash',closes:'crash',close:'crash',launch:'start',launching:'start',play:'start',startup:'start',boot:'start',opening:'start',log:'logs',crashlog:'logs',crashlogs:'logs',logfile:'logs',discord:'community',server:'community',support:'community',staff:'community',help:'community',download:'install',ipa:'install',sideload:'install',signing:'install',signed:'install',update:'updates',latest:'updates',build:'updates',version:'updates',iphone:'device',ipad:'device',mac:'device',macos:'device',ram:'memory',lag:'performance',stutter:'performance',fps:'performance',thermal:'performance',hot:'performance',controller:'controls',gamepad:'controls',joystick:'controls',touch:'controls',blackscreen:'black-screen',black:'black-screen',freeze:'stuck',frozen:'stuck',paid:'funding',payment:'funding',price:'funding',cost:'funding',donate:'funding',donation:'funding',crypto:'funding',tip:'funding',free:'funding'};
  const state={passages:null,promise:null,lastIntent:'',lastSource:null};
  const norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/gta\s*5/g,'gta v').replace(/[^a-z0-9+.-]+/g,' ').replace(/\s+/g,' ').trim();
  const words=v=>[...new Set(norm(v).split(' ').filter(Boolean).flatMap(w=>w.length<2||STOP.has(w)?[]:(ALIAS[w]&&ALIAS[w]!==w?[w,ALIAS[w]]:[w])))];
  const clean=v=>String(v||'').replace(/\s+/g,' ').trim();
  const textOf=node=>clean(node?.textContent||'');
  const linkFrom=(node,fallback)=>node?.querySelector?.('a[href]')?.getAttribute('href')||fallback;
  const makePassage=({question='',answer='',heading='',href,label,weight=1,type='section'})=>({question:clean(question),answer:clean(answer),heading:clean(heading),href,label,weight,type,haystack:norm(`${heading} ${question} ${answer}`),tokens:words(`${heading} ${question} ${answer}`)});

  async function parseSource([href,label,weight]){try{const res=await fetch(href,{cache:'no-cache'});if(!res.ok)return[];const doc=new DOMParser().parseFromString(await res.text(),'text/html'),main=doc.querySelector('main');if(!main)return[];const out=[];main.querySelectorAll('details').forEach(d=>{const q=textOf(d.querySelector('summary')),body=d.querySelector('.answer-body')||d,a=textOf(body);if(q.length>5&&a.length>12)out.push(makePassage({question:q,answer:a,heading:'FAQ',href:linkFrom(body,href),label,weight:weight+.85,type:'faq'}));});[...main.querySelectorAll('h1,h2,h3')].forEach(h=>{const title=textOf(h);if(!title)return;const chunks=[];let node=h.nextElementSibling,guard=0;while(node&&guard++<12&&!/^H[1-3]$/.test(node.tagName)){const t=textOf(node);if(t.length>=18)chunks.push(t);if(chunks.join(' ').length>1100)break;node=node.nextElementSibling;}const answer=clean(chunks.join(' ')).slice(0,1100);if(answer.length>=30)out.push(makePassage({question:title,answer,heading:title,href:linkFrom(h.parentElement||main,href),label,weight,type:'section'}));});main.querySelectorAll('p,li').forEach(node=>{const t=textOf(node);if(t.length<35||t.length>700)return;const section=node.closest('section,article,details'),h=section?.querySelector?.('h1,h2,h3,summary');out.push(makePassage({question:textOf(h),answer:t,heading:textOf(h)||label,href:linkFrom(node,href),label,weight:weight*.88,type:'paragraph'}));});return out;}catch{return[];}}
  function load(){if(state.promise)return state.promise;state.promise=Promise.all(SOURCES.map(parseSource)).then(g=>state.passages=g.flat()).catch(()=>state.passages=[]);return state.promise;}
  function intent(q){const n=norm(q);if(/\b(free|paid|payment|pay|price|cost|fee|charge|donate|donation|crypto|wallet|erc20|ethereum|solana|bitcoin|btc|litecoin|ltc|tip|support developer|support project)\b/.test(n))return'funding';if(/\b(discord|community|server|staff|support team|join server)\b/.test(n))return'community';if(/\b(crash|crashes|crashing|force close|forceclose|closes|close itself|won t open|wont open|not open)\b/.test(n))return'crash';if(/\b(black screen|blackscreen)\b/.test(n))return'black-screen';if(/\b(stuck|freeze|frozen|loading forever|never loads)\b/.test(n))return'stuck';if(/\b(install|download|ipa|sideload|signing|certificate)\b/.test(n))return'install';if(/\b(update|latest build|new build|version)\b/.test(n))return'updates';if(/\b(fps|lag|stutter|performance|thermal|hot|heat|resolution|msaa|metalfx|graphics)\b/.test(n))return'performance';if(/\b(controller|gamepad|joystick|touch controls|keyboard|mouse)\b/.test(n))return'controls';if(/\b(save|savegame|import save|progress)\b/.test(n))return'save';return'';}
  function domainAllowed(q){const n=norm(q);if(intent(q)==='funding')return true;if(/\b(gta v|grand theft auto|ios project|launcher|dxmt|metalfx|lowmem|memrestrict|ipa|iphone|ipad|macos|discord|community|crash|crashing|install|sideload|compatibility|controller|gamepad|fps|graphics|settings|update|build|logs|log folder|save|patch)\b/.test(n))return true;if(state.lastIntent&&words(q).length<=6)return true;return false;}
  function score(p,q){const n=norm(q),qt=words(q),it=intent(q);let s=0;if(p.question&&n===norm(p.question))s+=30;if(p.question&&(n.includes(norm(p.question))||norm(p.question).includes(n))&&n.length>5)s+=12;for(const t of qt){if(p.tokens.includes(t))s+=t.length>=7?3.2:2.2;if(p.question&&norm(p.question).includes(t))s+=1.6;}if(qt.length)s+=qt.filter(t=>p.tokens.includes(t)).length/qt.length*7;if(it==='crash'&&/crash|logs|log folder|troubleshoot|launch|start|play/.test(p.haystack))s+=8;if(it==='community'&&/discord|community|support|staff/.test(p.haystack))s+=9;if(it==='install'&&/install|ipa|sign|sideload|download/.test(p.haystack))s+=5;if(it==='updates'&&/update|release|build|latest/.test(p.haystack))s+=5;if(it==='performance'&&/performance|fps|memory|thermal|graphics|resolution/.test(p.haystack))s+=5;return s*p.weight;}
  function concise(text,max=620){const c=clean(text);if(c.length<=max)return c;const cut=c.slice(0,max),end=Math.max(cut.lastIndexOf('. '),cut.lastIndexOf('; '));return`${cut.slice(0,end>300?end+1:max-1).trim()}…`;}
  function crashEscalation(){return{text:"Aight, if GTA V still crashes after you've followed the troubleshooting steps, don't keep guessing. Join the Discord and send the crash log or the project's Logs folder to the staff/community so they can see what failed. Include your device, iOS version, build date/version, what you were doing when it crashed, and any settings you changed. That gives the crew something useful to diagnose.",topic:'troubleshooting',source:{href:'faq.html',label:'FAQ / Troubleshooting'},discord:true,suggestions:['Where can I find the logs?','Open troubleshooting guide']};}
  function fundingAnswer(q){const n=norm(q),asksWallet=/\b(donate|donation|crypto|wallet|erc20|ethereum|solana|bitcoin|btc|litecoin|ltc|tip|support developer|support project)\b/.test(n);const intro="Nope — the GTA V iOS Project is completely free. You will NEVER be asked to pay for an update, to play the game, or to unlock project features. If anyone claims payment is required for those things, don't treat that as an official project requirement.";const donation=" If you voluntarily want to support the developer, crypto donations are optional and never required:\n\nERC20: 0x2df6a507b418637D465fA3402Aa05D2cdF1BDb91\nSOL: J6CtXd23tQakYhRxqu6Q31HY5RmwGwkKNPdvNarD8iqm\nBTC: bc1qk3a8jq6zr3yy6e3yg035c4lmel08l3g53nskut\nLTC: ltc1qcw0qwdqepwyqwzf8x5exdhzgpxtzmjva49ke8a\n\nThank you!";return{text:intro+(asksWallet?donation:" You can support the developer voluntarily via crypto if you want, but it is totally optional. Ask me for the donation addresses if you need them."),topic:'funding',suggestions:asksWallet?['Is donating required?','Where can I join Discord?']:['Show crypto donation addresses','Where can I join Discord?']};}
  async function answer(question){const q=String(question||'').trim();if(!q||!domainAllowed(q))return null;const it=intent(q);if(it==='funding'){state.lastIntent='funding';return fundingAnswer(q);}const passages=await load(),ranked=passages.map(p=>({p,s:score(p,q)})).sort((a,b)=>b.s-a.s),best=ranked[0];if(it==='crash'&&/\b(still|always|keeps|keep|again|after|every time|clicking play|when i play|on launch|at launch)\b/i.test(q)){const r=crashEscalation();state.lastIntent='crash';state.lastSource=r.source;return r;}if(it==='community'){state.lastIntent='community';return{text:"You can join the GTA V iOS community on Discord. That's also where the current build instructions and direct staff/community support are handled.",topic:'community',source:{href:'community.html',label:'Community'},discord:true,suggestions:['Where do I download the latest build?','What should I send with a crash report?']};}const floor=words(q).length<=2?8.5:7;if(!best||best.s<floor){if(it==='crash')return crashEscalation();return null;}const p=best.p,text=p.type==='faq'?concise(p.answer):`Aight, here's what the project docs say: ${concise(p.answer)}`;const result={text,topic:it||'site-docs',source:{href:p.href||'faq.html',label:p.label||'Project docs'},discord:/discord|send the logs|send.*log|support/.test(norm(text)),suggestions:it==='crash'?['What if it still crashes?','Where can I find the logs?']:[]};state.lastIntent=it||'site-docs';state.lastSource=result.source;return result;}

  const svg=n=>`<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${n}"></use></svg>`;
  function appendUser(text){const m=document.querySelector('.ask-franklin-messages');if(!m)return;const r=document.createElement('div');r.className='ask-franklin-message user franklin-site-rag-message';const b=document.createElement('div');b.className='bubble';b.textContent=text;r.append(b);m.append(r);requestAnimationFrame(()=>m.scrollTop=m.scrollHeight);}
  function appendBot(text,o={}){const m=document.querySelector('.ask-franklin-messages');if(!m)return;const r=document.createElement('div');r.className='ask-franklin-message bot franklin-site-rag-message';r.innerHTML='<span class="mini-avatar">F</span>';const b=document.createElement('div');b.className='bubble';b.style.whiteSpace='pre-wrap';b.textContent=text;r.append(b);if(o.discord){const a=document.createElement('a');a.className='ask-franklin-discord';a.href=DISCORD;a.target='_blank';a.rel='noopener noreferrer';a.innerHTML=`Ask the crew on Discord ${svg('arrow-up-right')}`;b.append(document.createElement('br'),a);}if(o.source?.href){const a=document.createElement('a');a.className='ask-franklin-discord';a.href=o.source.href;a.innerHTML=`Open ${o.source.label||'source'} ${svg('arrow-right')}`;b.append(document.createElement('br'),a);}m.append(r);if(o.suggestions?.length){const w=document.createElement('div');w.className='ask-franklin-actions ask-franklin-related';o.suggestions.slice(0,2).forEach(x=>{const c=document.createElement('button');c.type='button';c.className='ask-franklin-chip';c.textContent=x;w.append(c);});m.append(w);}requestAnimationFrame(()=>m.scrollTop=m.scrollHeight);}
  function thinking(){const m=document.querySelector('.ask-franklin-messages');if(!m)return null;const r=document.createElement('div');r.className='ask-franklin-message bot is-thinking franklin-site-rag-message';r.innerHTML='<span class="mini-avatar">F</span><div class="bubble" aria-label="Franklin is checking the project docs"><i class="ask-franklin-dot"></i><i class="ask-franklin-dot"></i><i class="ask-franklin-dot"></i></div>';m.append(r);return r;}
  let busy=false;
  async function answerInUI(raw){const q=String(raw||'').trim();if(!q||busy)return;const i=document.querySelector('.ask-franklin-input'),s=document.querySelector('.ask-franklin-send');if(!i||!s)return;busy=true;s.disabled=true;appendUser(q);i.value='';i.style.height='auto';const wait=thinking();try{let r=await answer(q);if(!r&&window.FranklinExtended?.answer)r=await window.FranklinExtended.answer(q);else if(!r&&window.FranklinEngine?.answer)r=await window.FranklinEngine.answer(q);if(!r)r={text:"Aight, I don't have a reliable answer for that yet. I only handle GTA V and the GTA V iOS Project, and I won't make something up.",topic:'unknown',discord:true};if(window.FranklinWebLLM?.refine)r=await window.FranklinWebLLM.refine(q,r);wait?.remove();appendBot(r.text,r);window.gtavHaptics?.trigger?.('soft');}catch{wait?.remove();appendBot("Man, something went sideways. Try again, or ask the crew on Discord if you need help right now.",{discord:true});window.gtavHaptics?.trigger?.('warning');}finally{busy=false;s.disabled=!i.value.trim();i.focus({preventScroll:true});}}
  document.addEventListener('submit',e=>{const f=e.target instanceof Element?e.target.closest('.ask-franklin-form'):null;if(!f)return;e.preventDefault();e.stopImmediatePropagation();answerInUI(f.querySelector('.ask-franklin-input')?.value||'');},true);
  document.addEventListener('click',e=>{if(!(e.target instanceof Element))return;const c=e.target.closest('.ask-franklin-chip');if(!c)return;e.preventDefault();e.stopImmediatePropagation();answerInUI(c.textContent||'');},true);
  window.FranklinSiteRAG={answer,answerInUI,load,status:()=>({loaded:!!state.passages,passages:state.passages?.length||0,lastIntent:state.lastIntent})};
  if(window.requestIdleCallback)window.requestIdleCallback(()=>load(),{timeout:2500});else setTimeout(()=>load(),900);
})();